<template>
  <main class="field-page shared-account" dir="rtl">
    <header class="account-hero"><span class="account-brand"><v-icon color="white" size="19">mdi-elevator</v-icon> سان اپ</span><span class="account-eyebrow">حساب و دسترسی‌ها</span><h1>حساب من</h1><p>اطلاعات حساب و پروژه فعال شما در یک نگاه</p></header>
    <div class="account-body">
      <section class="account-identity" aria-labelledby="account-name"><span class="account-avatar" aria-hidden="true">{{ initial }}</span><div><h2 id="account-name">{{ name }}</h2><span>{{ roleName }}</span></div></section>
      <section class="account-panel" aria-labelledby="project-heading"><div class="account-panel-head"><span class="account-panel-icon"><v-icon color="#236d89" size="23">mdi-office-building-outline</v-icon></span><div><small>فضای کاری فعلی</small><h2 id="project-heading">{{ projectName }}</h2></div></div><router-link :to="{ name: 'projects' }" class="account-action">تغییر پروژه یا نقش <v-icon color="#246e8a" size="19">mdi-arrow-left</v-icon></router-link></section>
      <section class="account-panel" aria-labelledby="details-heading"><div class="account-section-title"><span>مشخصات من</span><h2 id="details-heading">اطلاعات حساب</h2></div><div class="account-fact"><span>شماره همراه</span><strong dir="ltr">{{ phone }}</strong></div><div class="account-fact"><span>شهر</span><strong>{{ city }}</strong></div><div class="account-fact"><span>نقش فعال</span><strong>{{ roleName }}</strong></div><router-link :to="{ name: 'personalInfo' }" class="account-action">مشاهده اطلاعات شخصی <v-icon color="#246e8a" size="19">mdi-arrow-left</v-icon></router-link></section>
      <section class="account-panel" aria-labelledby="access-heading"><div class="account-section-title"><span>دسترسی سریع</span><h2 id="access-heading">کارهای من</h2></div><router-link v-if="hasClient" :to="{ name: 'clientVisits' }" class="account-list-link"><v-icon color="#246e8a" size="20">mdi-clipboard-text-clock-outline</v-icon>درخواست‌ها و ویزیت‌ها<v-icon size="18">mdi-chevron-left</v-icon></router-link><router-link v-if="hasExpert" :to="{ name: 'tasks' }" class="account-list-link"><v-icon color="#246e8a" size="20">mdi-clipboard-check-outline</v-icon>مأموریت‌های من<v-icon size="18">mdi-chevron-left</v-icon></router-link><router-link v-if="hasExpert" :to="{ name: 'visitHistory' }" class="account-list-link"><v-icon color="#246e8a" size="20">mdi-history</v-icon>تاریخچه ویزیت<v-icon size="18">mdi-chevron-left</v-icon></router-link><router-link :to="{ name: hasExpert && !hasClient ? 'chatHistory' : 'clientSupport' }" class="account-list-link"><v-icon color="#246e8a" size="20">mdi-lifebuoy</v-icon>پشتیبانی و گفتگو<v-icon size="18">mdi-chevron-left</v-icon></router-link><router-link v-if="hasAcademy" :to="{ name: 'guideLine' }" class="account-list-link"><v-icon color="#246e8a" size="20">mdi-book-open-outline</v-icon>راهنمای استفاده<v-icon size="18">mdi-chevron-left</v-icon></router-link></section>
      <section class="account-panel" aria-label="راهنما و ارتباط"><router-link :to="{ name: 'authenticationPage' }" class="account-list-link"><v-icon color="#607d8d" size="20">mdi-card-account-details-outline</v-icon>مدارک هویتی<v-icon size="18">mdi-chevron-left</v-icon></router-link><router-link :to="{ name: 'rules' }" class="account-list-link"><v-icon color="#607d8d" size="20">mdi-file-document-outline</v-icon>قوانین و مقررات<v-icon size="18">mdi-chevron-left</v-icon></router-link><router-link :to="{ name: 'faq' }" class="account-list-link"><v-icon color="#607d8d" size="20">mdi-help-circle-outline</v-icon>سؤال‌های متداول<v-icon size="18">mdi-chevron-left</v-icon></router-link><router-link :to="{ name: 'contact' }" class="account-list-link"><v-icon color="#607d8d" size="20">mdi-phone-outline</v-icon>تماس با ما<v-icon size="18">mdi-chevron-left</v-icon></router-link><router-link :to="{ name: 'aboutUs' }" class="account-list-link"><v-icon color="#607d8d" size="20">mdi-information-outline</v-icon>درباره سان اپ<v-icon size="18">mdi-chevron-left</v-icon></router-link></section>
      <button type="button" class="account-logout" @click="exitOpen = true"><v-icon color="#a24641" size="19">mdi-logout</v-icon>خروج از حساب</button>
    </div>
    <v-bottom-sheet v-model="exitOpen" max-width="576"><v-sheet class="account-exit-sheet" dir="rtl"><h2>خروج از حساب</h2><p>برای ورود دوباره به شماره همراه و رمز عبور یا کد یک‌بارمصرف نیاز دارید.</p><div><v-btn outlined color="primary" :disabled="busy" @click="exitOpen = false">ماندن در حساب</v-btn><v-btn color="error" :loading="busy" :disabled="busy" @click="logout">خروج</v-btn></div></v-sheet></v-bottom-sheet>
  </main>
</template>
<script>
import { logoutSession } from '@/api/apiServiceLayer';
export default {
  data: () => ({ exitOpen: false, busy: false }),
  computed: {
    membership() { return this.$STORE.state.userConfig.userInfo || {}; },
    user() { return this.membership.user || {}; },
    hasClient() { return (this.$STORE.state.userConfig.navigation || []).some(item => item.route === 'home'); },
    hasExpert() { return (this.$STORE.state.userConfig.navigation || []).some(item => item.route === 'tasks'); },
    hasAcademy() { return (this.$STORE.state.userConfig.navigation || []).some(item => item.route === 'edu'); },
    name() { return [this.user.first_name, this.user.last_name].filter(Boolean).join(' ') || 'کاربر سان اپ'; },
    initial() { return this.name.charAt(0); },
    roleName() { const role = this.membership.role || {}; return role.verbose_name || ({ client: 'نماینده مشتری', assigned: 'کارشناس', supervised: 'سرپرست', project: 'مدیر پروژه' }[role.asset_scope]) || role.title || 'نقش مشخص نشده'; },
    projectName() { const project = this.membership.project || {}; return project.name_fa || project.name || 'پروژه مشخص نشده'; },
    phone() { return this.user.username || 'ثبت نشده'; },
    city() { const extended = this.user.extended || {}; return (extended.city && extended.city.name) || 'ثبت نشده'; },
  },
  methods: { async logout() { if (this.busy) return; this.busy = true; try { await logoutSession(); this.$router.replace({ name: 'login' }).catch(() => {}); } finally { this.busy = false; this.exitOpen = false; } } }
};
</script>
<style scoped>
