r-top:1px solid #edf2f4;font-size:12px}.account-fact span{color:#698392}.account-fact strong{font-size:12px;color:#2d5369;overflow-wrap:anywhere}.account-list-link{display:flex;align-items:center;gap:11px;min-height:49px;border-top:1px solid #edf2f4;color:#294f63;text-decoration:none;font-size:13px;font-weight:600}.account-list-link:first-of-type{border-top:0}.account-list-link .v-icon:last-child{margin-right:auto;color:#6d96a7}.account-logout{display:flex;align-items:center;justify-content:center;gap:9px;min-height:50px;width:100%;border:1px solid #f0ceca;border-radius:14px;background:#fff3f1;color:#a24641;font-size:13px;font-weight:700}.account-exit-sheet{padding:24px 20px calc(22px + env(safe-area-inset-bottom))}.account-exit-sheet h2{font-size:18px;margin:0 0 9px}.account-exit-sheet p{color:#627d8d;font-size:13px;line-height:1.8}.account-exit-sheet>div{display:flex;gap:9px;margin-top:18px}.account-exit-sheet .v-btn{flex:1}.shared-account a:focus-visible,.shared-account button:focus-visible{outline:3px solid #3799bd;outline-offset:3px}@media(max-width:350px){.account-hero{padding-left:16px;padding-right:16px}.account-body{padding-left:14px;padding-right:14px}.account-panel{padding:15px}}
</style>
